    nums.sort()
    result = []
    n = len(nums)

    for i in range(n - 2):
        # Skip duplicate values for the first element
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        left, right = i + 1, n - 1
        target = -nums[i]

        while left < right:
            sum_ = nums[left] + nums[right]

            if sum_ == target:
                # All three are unique because of sorting and skipping duplicates
