def levenshtein_distance(s1, s2):
    m, n = len(s1), len(s2)
    # Create a matrix to store distances
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize base cases
    for i in range(m + 1):
        dp[i][0] = i  # Deleting all characters of s2
    for j in range(n + 1):
        dp[0][j] = j  # Inserting all characters of s1

    # Fill the matrix
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],   # Deletion
                    dp[i][j - 1],   # Insertion
                    dp[i - 1][j - 1]  # Substitution
                )

    return dp[m][n]
