    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        # Check if mid is the target
        if arr[mid] == target:
            return mid

        # Determine which side is sorted
        if arr[left] <= arr[mid]:
            # arr[left..mid] is sorted
            if arr[left] <= target < arr[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
